(function () {
  function setupTabs(root, tabAttr, panelAttr) {
    var tabs = Array.prototype.slice.call(root.querySelectorAll('[' + tabAttr + ']'));
    var panels = Array.prototype.slice.call(root.querySelectorAll('[' + panelAttr + ']'));
    if (!tabs.length || !panels.length) return;
    function activate(key, focusTab) {
      tabs.forEach(function (tab) {
        var active = tab.getAttribute(tabAttr) === key;
        tab.classList.toggle('is-active', active);
        tab.setAttribute('aria-selected', active ? 'true' : 'false');
        tab.setAttribute('tabindex', active ? '0' : '-1');
        if (active && focusTab) tab.focus();
      });
      panels.forEach(function (panel) {
        var active = panel.getAttribute(panelAttr) === key;
        panel.classList.toggle('is-active', active);
        panel.hidden = !active;
      });
    }
    tabs.forEach(function (tab) {
      tab.addEventListener('click', function () { activate(tab.getAttribute(tabAttr), false); });
      tab.addEventListener('keydown', function (event) {
        var keys = ['ArrowRight', 'ArrowDown', 'ArrowLeft', 'ArrowUp', 'Home', 'End'];
        if (keys.indexOf(event.key) === -1) return;
        event.preventDefault();
        var index = tabs.indexOf(tab);
        var next = index;
        if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % tabs.length;
        if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + tabs.length) % tabs.length;
        if (event.key === 'Home') next = 0;
        if (event.key === 'End') next = tabs.length - 1;
        activate(tabs[next].getAttribute(tabAttr), true);
      });
    });
  }
  Array.prototype.slice.call(document.querySelectorAll('[data-crays-franchise-tabs]')).forEach(function (root) { setupTabs(root, 'data-crays-franchise-tab', 'data-crays-franchise-panel'); });
  Array.prototype.slice.call(document.querySelectorAll('.crays-owner-alliance-tabs-v1__layout')).forEach(function (root) { setupTabs(root, 'data-owner-alliance-tab', 'data-owner-alliance-panel'); });
  Array.prototype.slice.call(document.querySelectorAll('.crays-join-fit-tabs-v1__tabs-shell')).forEach(function (root) { setupTabs(root, 'data-join-fit-tab', 'data-join-fit-panel'); });

  Array.prototype.slice.call(document.querySelectorAll('[data-crays-advantages-slider]')).forEach(function (slider) {
    var track = slider.querySelector('[data-crays-advantages-track]');
    var cards = Array.prototype.slice.call(track ? track.querySelectorAll('.crays-franchise-advantage-slide') : []);
    var dots = Array.prototype.slice.call(slider.querySelectorAll('[data-crays-advantages-dot]'));
    var prev = slider.querySelector('[data-crays-advantages-prev]');
    var next = slider.querySelector('[data-crays-advantages-next]');
    var index = 0;
    var scrolling = false;

    function clamp(to) {
      return (to + cards.length) % cards.length;
    }

    function sync() {
      cards.forEach(function (card, i) {
        card.classList.toggle('is-active-slide', i === index);
      });
      dots.forEach(function (dot, i) {
        var active = i === index;
        dot.classList.toggle('is-active', active);
        if (active) {
          dot.setAttribute('aria-current', 'true');
        } else {
          dot.removeAttribute('aria-current');
        }
      });
    }

    function scrollToIndex(behavior) {
      var card = cards[index];
      if (!track || !card) return;
      scrolling = true;
      track.scrollTo({ left: Math.max(0, card.offsetLeft - track.offsetLeft), behavior: behavior || 'smooth' });
      window.setTimeout(function () { scrolling = false; }, behavior === 'auto' ? 80 : 720);
    }

    function go(to, behavior) {
      if (!cards.length) return;
      index = clamp(to);
      sync();
      scrollToIndex(behavior);
    }

    function nearest() {
      var trackLeft = track.getBoundingClientRect().left;
      var nearestIndex = 0;
      var nearestDistance = Infinity;
      cards.forEach(function (card, i) {
        var distance = Math.abs(card.getBoundingClientRect().left - trackLeft);
        if (distance < nearestDistance) {
          nearestDistance = distance;
          nearestIndex = i;
        }
      });
      return nearestIndex;
    }

    dots.forEach(function (dot, i) { dot.addEventListener('click', function () { go(i, 'smooth'); }); });
    if (prev) prev.addEventListener('click', function () { go(index - 1, 'smooth'); });
    if (next) next.addEventListener('click', function () { go(index + 1, 'smooth'); });
    if (track) {
      track.addEventListener('keydown', function (event) {
        if (event.key === 'ArrowRight') {
          event.preventDefault();
          go(index + 1, 'smooth');
        }
        if (event.key === 'ArrowLeft') {
          event.preventDefault();
          go(index - 1, 'smooth');
        }
      });
      track.addEventListener('scroll', function () {
        if (scrolling || !cards.length) return;
        window.requestAnimationFrame(function () {
          index = nearest();
          sync();
        });
      }, { passive: true });
    }
    go(0, 'auto');
  });
})();

(function () {
  var panel = document.querySelector('[data-crays-consent-panel]');
  if (!panel) return;
  var storageKey = 'crays-cookie-consent';
  function openPanel() {
    panel.hidden = false;
    panel.classList.add('is-open');
  }
  function closePanel(value) {
    if (value) {
      try { window.localStorage.setItem(storageKey, value); } catch (error) {}
    }
    panel.classList.remove('is-open');
    panel.hidden = true;
  }
  document.querySelectorAll('[data-crays-consent-open]').forEach(function (button) {
    button.addEventListener('click', openPanel);
  });
  panel.querySelectorAll('[data-crays-consent-close]').forEach(function (button) {
    button.addEventListener('click', function () { closePanel(button.getAttribute('data-crays-consent-close')); });
  });
})();
